function buildGoalDrivenPatchProposal(goal: string): { path: string; oldText: string; newText: string; summary: string } | null {
  const normalizedGoal = goal.trim();
  if (!normalizedGoal) {
    return null;
  }
  // Pattern: "... in <file> from '<old>' to '<new>' ..." (single or double quotes,
